'use strict';
module.exports={name:'插件工坊',apply(ctx){
 ctx.tool({name:'manage_plugins',description:'制作和扩展 aide 自身的插件。先 guide 获取真实协议，inspect 读取已有插件源码；prepare 用 manifest 与完整文本 files 生成语法检查过的 ZIP 和待确认安装/升级提案。enable/disable/remove 也只生成提案。不得声称已安装，不得绕过设置权限或用 shell 改注册表。',parameters:{type:'object',required:['action'],properties:{action:{type:'string',enum:['guide','list','inspect','prepare','enable','disable','remove']},id:{type:'string'},manifest:{type:'object'},files:{type:'object',additionalProperties:{type:'string'}},reason:{type:'string'}}},handler(){throw new Error('需由 aide 原生插件工坊执行器处理')}});
 ctx.tool({name:'manage_references',description:'根据用户提供的路径或资料地址登记、更新或移除引用，先生成待确认提案。list 查询元数据；upsert 提供 id、name、type 和 config；remove 指定 id。不会自动解开可见或可写锁；已有引用文档内容使用 read_file/write_file(source=引用ID)，仍遵循原有锁和审批。不得接收密码或密钥。',parameters:{type:'object',required:['action'],properties:{action:{type:'string',enum:['list','upsert','remove']},id:{type:'string'},name:{type:'string'},type:{type:'string',enum:['local','skill','link','sftp']},config:{type:'object',properties:{path:{type:'string'},url:{type:'string'},host:{type:'string'},port:{type:'integer'},username:{type:'string'},auth:{type:'string',enum:['none']}}},reason:{type:'string'}}},handler(){throw new Error('需由 aide 原生引用管理执行器处理')}});
}};
